  books = JSON.parse(await readFile(dataFile, 'utf8'));
  if (!Array.isArray(books)) throw new Error('Book file must contain an array');
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
  books = [];
  await writeFile(dataFile, '[]\n');
}

let pendingWrite = Promise.resolve();
function persistBooks() {
  const snapshot = `${JSON.stringify(books, null, 2)}\n`;
  pendingWrite = pendingWrite.then(() => writeFile(dataFile, snapshot));
  return pendingWrite;
}

function sendJson(response, status, payload) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  response.end(JSON.stringify(payload));
}

async function readRequestBody(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 32_000) throw Object.assign(new Error('Request is too large'), { status: 413 });
  }
  try {
    return JSON.parse(body || '{}');
  } catch {
    throw Object.assign(new Error('Please send valid JSON'), { status: 400 });
  }
}

async function handleApi(request, response, url) {
  if (url.pathname === '/api/books' && request.method === 'GET') {
    return sendJson(response, 200, books);
  }

  if (url.pathname === '/api/books' && request.method === 'POST') {
    let body;
    try {
      body = await readRequestBody(request);
    } catch (error) {
      return sendJson(response, error.status || 400, { error: error.message });
    }
    const title = typeof body.title === 'string' ? body.title.trim() : '';
    const author = typeof body.author === 'string' ? body.author.trim() : '';
    const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
    if (!title || !author) return sendJson(response, 400, { error: 'Add a title and an author to save this book.' });
    if (title.length > 200 || author.length > 160 || notes.length > 10_000) {
      return sendJson(response, 400, { error: 'One of those fields is longer than allowed.' });
    }
    const book = {
      id: randomUUID(),
      title,
      author,
      notes,
      status: 'reading',
      createdAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.unshift(book);
    try {
      await persistBooks();
      return sendJson(response, 201, book);
    } catch {
      books = books.filter((item) => item.id !== book.id);
      return sendJson(response, 500, { error: 'The book could not be saved. Please try again.' });
    }
  }

  const match = url.pathname.match(/^\/api\/books\/([\w-]+)(?:\/(finish))?$/);
  if (match) {
    const book = books.find((item) => item.id === match[1]);
    if (!book) return sendJson(response, 404, { error: 'Book not found.' });
    if (request.method === 'GET' && !match[2]) return sendJson(response, 200, book);
    if (request.method === 'PATCH' && match[2] === 'finish') {
      if (book.status !== 'finished') {
        book.status = 'finished';
